namespace LocalSpt5Esp;
internal sealed record SceneTemplate(string Id,string Name,string Role,string Side,int Difficulty,int Count,AiBirthPreset Birth);
internal sealed record SceneActor(ScenePoint Position,SceneTemplate Template);
internal sealed record SceneRelation(int First,int Second,bool Hostile);
internal sealed record MapScene(string Id,string Name,string Map,SceneActor[] Actors,SceneRelation[]? Relations=null);
internal static class SceneTemplates {
 static readonly List<SceneTemplate> templates=new();static readonly List<MapScene> scenes=new();static readonly Queue<SceneActor> restore=new();
 static int wanted,finished,made;
 static MapScene? restoringScene;static readonly Dictionary<string,(LiveActorReference Actor,bool Paused)> staged=new();
 static bool loaded,corrupt;static ConfigEntry<string> selected=null!;static ConfigEntry<bool> exclusive=null!;static bool sceneActive;static IntPtr restoreWorld;static string restoreMap="",name="",notice="";static Vector2 scroll;
 static ConfigEntry<KeyCode> saveKey=null!,loadKey=null!;static string quickScene="";
 static string Home=>Path.Combine(BepInEx.Paths.PluginPath,"LocalSpt5ESP");
 internal static bool Exclusive=>sceneActive&&exclusive.Value&&RaidClock.Active;
 internal static void Reset(){ReleaseStaged();restore.Clear();restoreWorld=IntPtr.Zero;sceneActive=false;wanted=finished=made=0;}
 internal static bool IsStaging(Player actor)=>staged.Values.Any(e=>e.Actor.Pointer==actor.Pointer&&e.Actor.Profile==actor.ProfileId);
 internal static void ResumeStaged(Player actor){foreach(var key in staged.Where(p=>p.Value.Actor.Pointer==actor.Pointer&&p.Value.Actor.Profile==actor.ProfileId).Select(p=>p.Key).ToArray()){var entry=staged[key];staged[key]=(entry.Actor,false);}}
 internal static void Restored(SceneTemplate template,Player actor){staged[template.Id]=(new(Singleton<GameWorld>.Instance!,actor),AiTestControl.IsPaused(actor));AiTestControl.SetPaused(new[]{actor},true);}
 internal static void Restored(string key,Player actor){if(restoringScene==null)return;var template=restoringScene.Actors.Select(a=>a.Template).FirstOrDefault(t=>t.Id==key);if(template!=null)Restored(template,actor);}
 static void ReleaseStaged(){if(restoringScene?.Relations!=null){var pairs=new List<(Player First,Player Second,bool Hostile)>();foreach(var relation in restoringScene.Relations)try{if(staged.TryGetValue(restoringScene.Actors[relation.First].Template.Id,out var left)&&staged.TryGetValue(restoringScene.Actors[relation.Second].Template.Id,out var right))pairs.Add((left.Actor.Resolve(),right.Actor.Resolve(),relation.Hostile));}catch{}AiActorControl.RestoreSceneRelations(pairs);}foreach(var entry in staged.Values)try{var actor=entry.Actor.Resolve();AiTestControl.SetPaused(new[]{actor},entry.Paused);}catch{}staged.Clear();restoringScene=null;}
 internal static void CancelRestore(){restore.Clear();ReleaseStaged();notice="已取消剩余场景载入；保留已生成角色。";}
 internal static void SceneJobFinished(int actual,int requested){finished+=requested;made+=actual;}
 static void ValidateMap(MapScene scene){if(scene==null||string.IsNullOrWhiteSpace(scene.Map)||scene.Actors==null||scene.Actors.Length>256)throw new ArgumentException("地图场景无效。");foreach(var actor in scene.Actors){if(actor==null||actor.Position==null||!float.IsFinite(actor.Position.X)||!float.IsFinite(actor.Position.Y)||!float.IsFinite(actor.Position.Z)||actor.Template.Count!=1)throw new ArgumentException("场景位置或数量无效。");Validate(actor.Template);}if(scene.Relations!=null&&(scene.Relations.Length>32640||scene.Relations.Any(r=>r.First<0||r.Second<0||r.First>=scene.Actors.Length||r.Second>=scene.Actors.Length||r.First==r.Second)))throw new ArgumentException("场景关系索引无效。");}
 internal static void Initialize(){selected=FeatureConfig.Bind("50. 玩具枪工具","AI scene template","玩具枪 AI 模板 ID","");exclusive=FeatureConfig.Bind("49. AI 动作导演","Exclusive saved scene","载入场景时禁止自然刷新 AI",true,"本模组手动和玩具枪生成仍允许；离开战局后自动解除场景接管。");saveKey=FeatureConfig.Bind("49. AI 动作导演","Save map scene key","保存本图 AI 场景键",KeyCode.None);loadKey=FeatureConfig.Bind("49. AI 动作导演","Load map scene key","载入本图 AI 场景键",KeyCode.None,"重复载入最近选用的本图场景；未选用时使用本图最后保存的场景，会替换当前地图 AI。");}
 static void Load(){if(loaded)return;loaded=true;try{templates.AddRange(PresetStorage.Load<SceneTemplate>(Path.Combine(Home,"director-ai-templates.json")));scenes.AddRange(PresetStorage.Load<MapScene>(Path.Combine(Home,"director-map-scenes.json")));foreach(var entry in templates)Validate(entry);foreach(var scene in scenes)ValidateMap(scene);}catch(Exception e){corrupt=true;notice="存档读取失败，原文件保留："+e.Message;}}
 static void Validate(SceneTemplate entry){if(string.IsNullOrWhiteSpace(entry.Role)||entry.Count is <1 or >100||entry.Difficulty is <0 or >3||entry.Birth==null||!Enum.TryParse<WildSpawnType>(entry.Role,out _))throw new ArgumentException("AI 模板参数无效。");if(entry.Birth.Scene!=null)DirectorRules.Validate(entry.Birth.Scene);AiBodyHealth.Validate(entry.Birth.BodyHealth);if(entry.Birth.LockedPose!=null)DirectorRules.ValidateLocked(entry.Birth.LockedPose);if(entry.Birth.Effects!=null)foreach(var effect in entry.Birth.Effects)if(!BuffRules.Common.Any(b=>b.Type==effect.Type)||!Enum.TryParse<EBodyPart>(effect.Part,out _)||!float.IsFinite(effect.Seconds)||effect.Seconds<=0||!float.IsFinite(effect.Strength)||effect.Strength<=0)throw new ArgumentException("模板状态无效。");}
 static void Save(){if(corrupt)throw new InvalidOperationException("存档读取失败，未覆盖原文件。");PresetStorage.Save(Path.Combine(Home,"director-ai-templates.json"),templates);PresetStorage.Save(Path.Combine(Home,"director-map-scenes.json"),scenes);}
 internal static SceneTemplate[] Saved {get{Load();return templates.ToArray();}}
 internal static SceneTemplate? Selected {get{Load();return templates.FirstOrDefault(t=>t.Id==selected.Value);}}
 internal static void ClearSelection(){selected.Value="";}
 static Vector2 pickerScroll;
 internal static void DrawPicker(Rect rect){Load();InterfaceMenu.Label(new Rect(rect.x,rect.y,rect.width,26),"保存的 AI 模板",InterfaceMenu.Accent,16);if(InterfaceMenu.Button(new Rect(rect.x,rect.y+34,rect.width,30),"使用上方类型与当前出生设置",Selected==null)){ClearSelection();ToyDeveloper.UseTemplate();}name=InterfaceMenu.Field(new Rect(rect.x,rect.y+76,Math.Max(90,rect.width-98),30),name);if(InterfaceMenu.Button(new Rect(rect.xMax-90,rect.y+76,90,30),"保存模板"))Action(()=>SaveTemplate(false));var view=new Rect(rect.x,rect.y+118,rect.width,Math.Max(70,rect.height-152));pickerScroll=GUI.BeginScrollView(view,pickerScroll,new Rect(0,0,rect.width-22,Math.Max(view.height-1,templates.Count*56)));for(int i=0;i<templates.Count;i++){var entry=templates[i];if(InterfaceMenu.Button(new Rect(2,i*56,rect.width-30,48),entry.Name+" · "+(AiSpawnCatalog.Options.FirstOrDefault(o=>o.Role==entry.Role)?.Name??entry.Role),selected.Value==entry.Id))Action(()=>Choose(entry.Id));}if(templates.Count==0)InterfaceMenu.Paragraph(new Rect(6,8,rect.width-36,64),"还没有模板。可在 AI 工作台保存出生设置或已选角色，再到这里直接选用。",null,12);GUI.EndScrollView();InterfaceMenu.Label(new Rect(rect.x,rect.yMax-26,rect.width,24),Selected==null?"当前使用类型与出生设置":"模板优先："+Selected.Name,InterfaceMenu.Accent,12);}
 internal static void Choose(string id){Load();if(!templates.Any(t=>t.Id==id))throw new ArgumentException("模板不存在。");selected.Value=id;ToyDeveloper.UseTemplate();notice="玩具枪已选择模板："+Selected!.Name;}
 internal static SceneTemplate Capture(Player actor,string title,bool portable=true){
  var appearance=new Dictionary<string,string>();var customization=actor.Profile?.Customization;if(customization!=null)foreach(var pair in customization)appearance[pair.Key.ToString()]=pair.Value.ToString();
  var current=Singleton<GameWorld>.Instance;var owner=actor.AIData?.BotOwner;var relation=owner!=null&&current?.MainPlayer!=null?AiActorControl.Relation(owner,current.MainPlayer):null;int playerRelation=relation==true?2:relation==false||Plugin.Self.IgnoreAI.Value?1:0;var birth=new AiBirthPreset(0,100,AiSceneDirector.OriginalPaused(actor),actor.ActiveHealthController!=null&&(AiActorControl.IndividuallyProtected(actor.ActiveHealthController)||Plugin.Self.AIGod.Value),true,playerRelation,0,Array.Empty<string>(),EBodyPart.LeftLeg,600,1,AiSceneDirector.For(actor,portable),AiBodyHealth.Capture(actor),null,AiSceneEquipment.Capture(actor),appearance,actor.Profile?.Nickname??"",CharacterBuffs.CaptureSceneDetailed(actor),ModelPoseLock.Export(actor));
  return new(Guid.NewGuid().ToString("N"),title,actor.Profile?.Info?.Settings?.Role.ToString()??"assault",actor.Profile?.Side.ToString()??"Savage",Math.Clamp((int)(actor.Profile?.Info?.Settings?.BotDifficulty??(BotDifficulty)1),0,3),1,birth);
 }
 internal static void Spawn(GameWorld current,Vector3 point,SceneTemplate value,bool exact=false){Validate(value);var option=AiSpawnCatalog.Options.FirstOrDefault(o=>o.Role==value.Role)??new AiSpawnOption("场景",value.Name,value.Role,value.Side,value.Role.StartsWith("boss",StringComparison.OrdinalIgnoreCase));AiSpawnService.Enqueue(current,point,option,value.Difficulty,value.Count,value.Birth with{SceneKey=exact?value.Id:""},"导演模板 · "+value.Name,exact);}
 static void SaveTemplate(bool actor){Load();if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("请输入模板名称。");SceneTemplate entry;if(actor){var target=AiTestControl.PoseSelection.FirstOrDefault()??throw new ArgumentException("请先选择 AI。");entry=Capture(target,name.Trim());}else{var option=ImpactAiSpawner.CurrentOption;entry=new(Guid.NewGuid().ToString("N"),name.Trim(),option.Role,option.Side,ImpactAiSpawner.CurrentDifficulty,ImpactAiSpawner.CurrentCount,AiSpawnPresets.Snapshot());}Validate(entry);templates.Add(entry);selected.Value=entry.Id;Save();notice="已保存 AI 模板；点击玩具枪生成后射击地面使用："+entry.Name;}
 static bool SceneActor(Player? actor)=>actor!=null&&!actor.IsYourPlayer&&(actor.IsAI||actor.AIData?.BotOwner!=null)&&actor.HealthController?.IsAlive==true&&actor.Profile?.Info?.Settings?.Role!=WildSpawnType.shooterBTR;
 static Player[] All(GameWorld current){var list=new List<Player>();var alive=current.AllAlivePlayersList;if(alive!=null)for(int i=0;i<alive.Count;i++)if(SceneActor(alive[i]))list.Add(alive[i]);return list.ToArray();}
 static void SaveMap(){
  Load();if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("请输入场景名称。");
  var current=Singleton<GameWorld>.Instance??throw new ArgumentException("请进入战局。");var actors=All(current);if(actors.Length>256)throw new ArgumentException("单个场景最多 256 名 AI。");
  var saved=actors.Select(actor=>new SceneActor(new(actor.Position.x,actor.Position.y,actor.Position.z),Capture(actor,actor.Profile?.Nickname??"AI",false))).ToArray();
  var relations=new List<SceneRelation>();for(int i=0;i<actors.Length;i++)for(int j=i+1;j<actors.Length;j++){var owner=actors[i].AIData?.BotOwner;if(owner==null)continue;var rule=AiActorControl.Relation(owner,actors[j]);if(rule.HasValue)relations.Add(new(i,j,rule.Value));}
  var scene=new MapScene(Guid.NewGuid().ToString("N"),name.Trim(),current.LocationId,saved,relations.ToArray());ValidateMap(scene);scenes.Add(scene);quickScene=scene.Id;Save();notice=$"已保存 {actors.Length} 名 AI 的位置、装备、外观、血量、动作和 {relations.Count} 对自定义关系。";
 }
 static void RestoreMap(MapScene scene){var current=Singleton<GameWorld>.Instance??throw new ArgumentException("请进入战局。");if(!string.Equals(scene.Map,current.LocationId,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("该场景属于其他地图。");ValidateMap(scene);foreach(var actor in scene.Actors)if(!NavMesh.SamplePosition(new Vector3(actor.Position.X,actor.Position.Y,actor.Position.Z),out _,3,NavMesh.AllAreas))throw new ArgumentException("场景角色附近没有导航地面，旧 AI 未清除。");AiSpawnService.Cancel(false);Reset();AiSceneEquipment.Reset();ModelPoseLock.Reset();AiSceneDirector.Reset();var removed=AiActorControl.Delete(All(current));AiActorControl.Reset();restore.Clear();restoringScene=scene;quickScene=scene.Id;foreach(var actor in scene.Actors)restore.Enqueue(actor);restoreWorld=current.Pointer;restoreMap=scene.Map;sceneActive=true;wanted=scene.Actors.Length;finished=made=0;notice=$"已移除 {removed} 名旧 AI；正在还原 {restore.Count} 名 AI。";}
 internal static void Tick(GameWorld? current){if(current==null||restoreWorld!=IntPtr.Zero&&current.Pointer!=restoreWorld){Reset();return;}if(!InterfaceMenu.InputBlocked){if(loadKey.Value!=KeyCode.None&&Input.GetKeyDown(loadKey.Value))Action(()=>{Load();var scene=scenes.FirstOrDefault(s=>s.Id==quickScene&&string.Equals(s.Map,current.LocationId,StringComparison.OrdinalIgnoreCase))??scenes.LastOrDefault(s=>string.Equals(s.Map,current.LocationId,StringComparison.OrdinalIgnoreCase))??throw new ArgumentException("本图还没有保存场景。");RestoreMap(scene);});else if(saveKey.Value!=KeyCode.None&&Input.GetKeyDown(saveKey.Value))Action(()=>{if(string.IsNullOrWhiteSpace(name))name="场景 "+DateTime.Now.ToString("yyyyMMdd-HHmmss");SaveMap();});}if(restore.Count==0){if(wanted>0&&finished>=wanted)ReleaseStaged();return;}if(current.Pointer!=restoreWorld||!string.Equals(current.LocationId,restoreMap,StringComparison.OrdinalIgnoreCase)){restore.Clear();return;}if(AiSpawnService.QueueCount>=4)return;var next=restore.Dequeue();try{Spawn(current,new(next.Position.X,next.Position.Y,next.Position.Z),next.Template,true);notice="剩余场景角色待排队："+restore.Count+"；"+AiSpawnService.Status;}catch(Exception e){finished++;notice="部分场景角色还原失败："+next.Template.Name+" · "+e.Message;Plugin.Self.Log.LogWarning(notice);}}
 static void Action(Action work){try{work();}catch(Exception e){notice=e.Message;FeatureToasts.Show(notice);}}
 internal static void Draw(Rect rect,bool maps=false){Load();scroll=GUI.BeginScrollView(rect,scroll,new Rect(0,0,rect.width-20,Math.Max(650,320+(maps?scenes.Count:templates.Count)*134)));float x=8,y=8,w=rect.width-36,half=(w-12)/2;InterfaceMenu.Label(new Rect(x,y,w,32),maps?"地图 AI 场景存档":"AI 模板",InterfaceMenu.Accent,21);y+=46;name=InterfaceMenu.Field(new Rect(x,y,w,32),name);y+=44;
  if(maps){if(InterfaceMenu.Button(new Rect(x,y,w,36),"保存当前地图全部 AI 状态"))Action(SaveMap);y+=48;InterfaceMenu.DrawEntry(exclusive,new Rect(x,y,w,80));y+=92;
   foreach(var scene in scenes.ToArray()){InterfaceMenu.Label(new Rect(x,y,w,26),$"{scene.Name} · {scene.Map} · {scene.Actors.Length} AI",null,14);y+=34;if(InterfaceMenu.Button(new Rect(x,y,half,34),"载入并替换当前地图 AI"))Action(()=>RestoreMap(scene));if(InterfaceMenu.Button(new Rect(x+half+12,y,half,34),"删除此场景存档"))Action(()=>{scenes.Remove(scene);Save();});y+=60;}
   if(InterfaceMenu.Button(new Rect(x,y,w,32),"结束场景接管，允许自然刷新")){sceneActive=false;notice="已解除场景接管。";}y+=44;
  }else{
   if(InterfaceMenu.Button(new Rect(x,y,half,36),"保存当前出生设置"))Action(()=>SaveTemplate(false));if(InterfaceMenu.Button(new Rect(x+half+12,y,half,36),"保存首个所选 AI"))Action(()=>SaveTemplate(true));y+=52;
   foreach(var entry in templates.ToArray()){InterfaceMenu.Label(new Rect(x,y,w,26),entry.Name+" · "+entry.Role+(selected.Value==entry.Id?" · 玩具枪使用中":""),null,14);y+=34;float col=(w-20)/3;if(InterfaceMenu.Button(new Rect(x,y,col,34),"玩具枪生成",selected.Value==entry.Id))Action(()=>Choose(entry.Id));if(InterfaceMenu.Button(new Rect(x+col+10,y,col,34),"载入出生编辑"))Action(()=>{AiSpawnPresets.Load(entry.Birth);notice="已载入模板参数。";});if(InterfaceMenu.Button(new Rect(x+2*(col+10),y,col,34),"删除模板"))Action(()=>{templates.Remove(entry);if(selected.Value==entry.Id)selected.Value="";Save();});y+=58;}
  }
  InterfaceMenu.Paragraph(new Rect(x,y,w,92),notice+"\n"+(maps&&wanted>0?$"场景实际生成 {made}/{wanted} · 已结束请求 {finished} · 待排队 {restore.Count}\n"+AiSpawnService.Status+"\n":"")+(maps?"同地图载入会替换当前 AI；不替换 BTR 射手。保存穿戴与枪械配件，不保存背包储物格内物资。":"模板包含类型、出生参数、动作、行为限制与已选枪械。保存所选 AI 时还包含其穿戴和外观。"),InterfaceMenu.Accent,12);GUI.EndScrollView();}
}
